    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    for (int t = 0; t < N; t += TILE_SIZE * UNROLL_FACTOR) {
        // Prefetch multiple tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int tiled_k = t + i * TILE_SIZE + threadIdx.x;

